import { Group, PlaneGeometry, Mesh, MeshBasicNodeMaterial, Color } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, sin, dot, vec2, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Colors from visual spec ---
  const paper = new Color('#e8ecf2');
  const surface = new Color('#0b0b10');
  const ink = new Color('#16161d');
  const accent = new Color('#ff2a38');

  // --- Plane dimensions (based on atlas region 512x320, aspect 1.6) ---
  const width = 3.2;
  const height = 2.0;
  const geometry = new PlaneGeometry(width, height);

  // --- Procedural gradient with subtle grain ---
  const vUv = uv();
  // Vertical gradient from paper (top) to surface (bottom) with slight ink at top edge
  const gradientT = smoothstep(0.0, 1.0, vUv.y);
  const colorA = vec3(paper.r, paper.g, paper.b);
  const colorB = vec3(ink.r, ink.g, ink.b).mul(0.3); // dark tint
  const colorC = vec3(surface.r, surface.g, surface.b);
  // Mix: top = mix(colorA, colorB, 0.2), bottom = colorC
  const top = mix(colorA, colorB, uniform(0.2));
  const bottom = colorC;
  const base = mix(top, bottom, gradientT);

  // Subtle grain using sin-based pseudorandom
  const grainSeed = vUv.mul(vec2(12.9898, 78.233));
  const grain = sin(dot(grainSeed, vec2(127.1, 311.7))).mul(0.02);
  const finalColor = base.add(grain);

  const material = new MeshBasicNodeMaterial();
  material.colorNode = finalColor;

  const plane = new Mesh(geometry, material);
  plane.position.set(0, 0, 0);
  group.add(plane);

  // --- Text content ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const bodyText = textItems.find(item => item.role === 'body');
  const content = bodyText?.text ?? 'A machined-metal watch atelier landing with catalog, pricing, jo';
  const fontSize = 0.13; // body scene-unit height per design tokens

  const text = ctx.fontAtlas.createText(content, {
    fontSize: fontSize,
    color: paper.getHexString(), // '#e8ecf2'
    align: 'center',
    maxWidthPx: width * 200, // approximate; text should wrap within plane width
    letterSpacingPx: 0.01 * fontSize // small spacing
  });
  // Position text at center of plane
  text.position.set(0, 0.05, 0.01); // slightly in front
  group.add(text);

  // --- No interaction handlers ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // Dispose text children (font atlas content)
    text.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
    // Kill any GSAP timelines (none)
  };

  return group;
}
